module barrel_shifter_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;

  reg [7:0] in;
  reg [2:0] ctrl;
  wire [7:0] out; 

barrel_shifter uut(.in(in), .ctrl(ctrl), .out(out));

integer error = 0;

initial begin
        in= 8'd0;  ctrl=3'd0; //no shift
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

        #10 in=8'd128; ctrl= 3'd4; //shift 4 bit
        #10 error = (out==8)?error : error+1;
        #10 in=8'd128; ctrl= 3'd2; //shift 2 bit
        #10 error = (out==32)?error : error+1;
        #10 in=8'd128; ctrl= 3'd1; //shift by 1 bit
        #10 error = (out==64)?error : error+1;
        #10 in=8'd255; ctrl= 3'd7; //shift by 7bit
        #10 error = (out==1)?error : error+1;
    // end
    // initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    //     $monitor("Input=%d, Control=%d, Output=%d",in,ctrl,out);
    // end
        if (error == 0) begin
            $display("=========== Your Design Passed ===========");
            end
        else begin
            $display("=========== Test completed with %d failures ===========", error);
        end
        $finish;
    end




        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "out,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", out);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;
        integer s;
        reg [7:0] temp_mask;

    // 1. DECLARE VARIABLES FIRST (Top of block)




    // 2. THEN WAIT for original tests
    // As per instructions, we wait for the signal (initially 1) to start our phase.
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting deterministic mutation testing stimuli...");

    // Initialize inputs
    in = 8'h00;
    ctrl = 3'b000;
    #10;

    // Strategy: Exhaustive Shift Amount Testing
    // Iterate through all possible shift amounts (0 to 7)
    for (s = 0; s < 8; s = s + 1) begin
        ctrl = s; // Set control bits (truncates integer to 3 bits)

        // Sub-Test 1: Walking 1s
        // Verifies that each bit is correctly routed to its destination for the current shift.
        // Detects: Broken connections, wrong bit indices, stuck-at-0 on data path.
        for (i = 0; i < 8; i = i + 1) begin
            in = (1 << i);
            #10;
        end

        // Sub-Test 2: Walking 0s
        // Verifies that 0s propagate correctly (inverse of Walking 1s).
        // Detects: Stuck-at-1 on data path, OR-type shorts.
        for (i = 0; i < 8; i = i + 1) begin
            temp_mask = (1 << i);
            in = ~temp_mask;
            #10;
        end

        // Sub-Test 3: Alternating Patterns
        // Verifies adjacent bit independence (crosstalk or shorted adjacent wires).
        in = 8'hAA; // 10101010
        #10;
        in = 8'h55; // 01010101
        #10;

        // Sub-Test 4: Boundary Fill
        // Verifies full bus width operation.
        in = 8'hFF; // All 1s
        #10;
        in = 8'h00; // All 0s
        #10;
    end

    // Corner Case: Rapid Control Transitions
    // Keep data constant (All 1s) and sweep control fast to expose potential timing/glitch issues
    // or sensitivity list omissions in behavioral models (though this is structural).
    in = 8'hFF;
    for (s = 0; s < 8; s = s + 1) begin
        ctrl = s;
        #5;
    end

    // Corner Case: Rapid Data Transitions
    // Keep control constant (Shift 4) and toggle MSB/LSB rapidly.
    ctrl = 3'd4;
    in = 8'h80; #5;
    in = 8'h01; #5;
    in = 8'h80; #5;
    in = 8'h01; #5;

    // 4. Handover
    $display("LLM: Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
    // DO NOT call $finish here.
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule
